<?php declare(strict_types=1);namespace App\Controllers\Admin;use App\Controllers\Controller;abstract class AdminController extends Controller{protected string $layout='layouts/admin';protected function multilang(mixed $W):array{if(!is_array($W)){return[];}$w=[];foreach($W as $d=>$t){if(in_array($d,\App\Core\I18n::LANGUAGES,true)&&is_string($t)&&trim($t)!==''){$w[$d]=trim($t);}}return $w;}}